UPDATE reviews
SET body = (
  SELECT CASE reviews.rating
    WHEN 5 THEN scopes.scope || 'deliverycomplete；' || scopes.constraint_fact || '；currenttranslatedtranslatedrecordtranslatedtranslated，translated Home translated has translatedfixednoise reductiontranslatedalternativethistranslatedmeasured。'
    WHEN 4 THEN scopes.scope || 'completeastranslatedtranslated can ；' || scopes.constraint_fact || '；quotationandremovalfixtranslatedresponsibilityalreadywritetranslated，translatedtranslatedtranslatedtranslatedstilltranslatedtranslatedthistranslatedretest。'
    ELSE scopes.scope || 'locationstranslatedafterstill has translatedtranslated；' || scopes.constraint_fact || '；translated Home translatedmodifytranslated，musttranslatedproperty managementallowed hours translatedtranslatedafterthentranslatedcounts。'
  END
  FROM scopes
  WHERE scopes.n = CAST((CAST(substr(reviews.review_id, -4) AS INTEGER) + 2) / 3 AS INTEGER)
)
WHERE review_id GLOB 'review_[0-9][0-9][0-9][0-9]';

