UPDATE merchants
SET name = CASE merchant_id
    WHEN 'merchant_0001' THEN 'BaiSound Soft Furnishings'
    WHEN 'merchant_0002' THEN 'OrangeLine Network'
    ELSE (SELECT scopes.scope || CASE CAST(substr(merchants.merchant_id,-4) AS INTEGER) % 3 WHEN 1 THEN 'translatedtranslatedtranslatedtranslated' WHEN 2 THEN 'translatedtranslatedworktranslated' ELSE 'fixtranslatedtranslatedtranslated' END FROM scopes WHERE scopes.n=CAST((CAST(substr(merchants.merchant_id,-4) AS INTEGER)+2)/3 AS INTEGER))
  END,
  address = (SELECT scopes.scope || '—' || CASE CAST(substr(merchants.merchant_id,-4) AS INTEGER) % 3
    WHEN 1 THEN 'translatedtranslatedRoad translatedtranslatedservicetranslated（translatedtranslatedaftertranslatedtranslatedtranslatedtranslatedtranslatedtranslated）'
    WHEN 2 THEN 'translatedtranslatedtranslatedRoad translatedtranslatedworkroom（ not translatedtranslatedtranslatedtranslatedtranslatedtranslated）'
    ELSE 'translatedtranslatedtranslatedRoad materialtranslatedtranslatedtranslated（onlywork hours translatedtranslated）'
  END FROM scopes WHERE scopes.n=CAST((CAST(substr(merchants.merchant_id,-4) AS INTEGER)+2)/3 AS INTEGER)),
  tags = (SELECT scopes.scope || ',' || CASE CAST(substr(merchants.merchant_id,-4) AS INTEGER) % 3
    WHEN 1 THEN ' can translatedtranslatedtranslated,currenttranslatedtranslated,rentalspace'
    WHEN 2 THEN ' low-noise translatedtranslated,translatedtranslatedquotation,property management hours '
    ELSE 'removalfixtranslated,evidencetranslatedtranslated,neighbornotification'
  END FROM scopes WHERE scopes.n=CAST((CAST(substr(merchants.merchant_id,-4) AS INTEGER)+2)/3 AS INTEGER))
WHERE merchant_id GLOB 'merchant_[0-9][0-9][0-9][0-9]';
